DECLARE
  v_subtotal DECIMAL(12, 2);
  v_tax_amount DECIMAL(12, 2);
  v_total DECIMAL(12, 2);
BEGIN
  -- Calculate subtotal from line items
  SELECT COALESCE(SUM(line_total), 0) INTO v_subtotal
  FROM invoice_line_items
  WHERE invoice_id = COALESCE(NEW.invoice_id, OLD.invoice_id);
  
  -- Get tax rate from invoice
  SELECT tax_rate INTO v_tax_amount
  FROM invoices
  WHERE id = COALESCE(NEW.invoice_id, OLD.invoice_id);
  
  -- Calculate tax and total
  v_tax_amount := v_subtotal * (COALESCE(v_tax_amount, 0) / 100);
  v_total := v_subtotal + v_tax_amount;
  
  -- Update invoice
  UPDATE invoices
  SET subtotal = v_subtotal,
      tax_amount = v_tax_amount,
      total = v_total
  WHERE id = COALESCE(NEW.invoice_id, OLD.invoice_id);
  
  RETURN NEW;
END;

declare
  new_org_id uuid;
  org_name text;
begin
  -- Friendly default org name
  org_name := coalesce(new.raw_user_meta_data->>'full_name', new.email, 'New Org');

  -- Create an org for this user
  insert into public.orgs (id, name)
  values (gen_random_uuid(), org_name)
  returning id into new_org_id;

  -- Create the user's profile linked to that org
  insert into public.profiles (id, email, role, org_id)
  values (new.id, new.email, 'admin', new_org_id)
  on conflict (id) do update
  set email = excluded.email;

  return new;
end;

declare
  v_org_id uuid;
  v_email text;
begin
  v_email := new.email;

  -- 1) create org for this user
  insert into public.orgs (name)
  values (coalesce(v_email, 'New Org'))
  returning id into v_org_id;

  -- 2) create profile
  insert into public.profiles (id, org_id, email, role, full_name)
  values (
    new.id,
    v_org_id,
    v_email,
    'admin',
    coalesce(new.raw_user_meta_data->>'full_name', null)
  )
  on conflict (id) do update
    set email = excluded.email;

  return new;
end;

