  IF TG_OP = 'DELETE' THEN
    PERFORM public.recalculate_invoice_payment_totals(OLD.invoice_id);
    RETURN OLD;
  END IF;

  PERFORM public.recalculate_invoice_payment_totals(NEW.invoice_id);

  IF TG_OP = 'UPDATE' AND OLD.invoice_id IS DISTINCT FROM NEW.invoice_id THEN
    PERFORM public.recalculate_invoice_payment_totals(OLD.invoice_id);
  END IF;

  RETURN NEW;
END;

DECLARE
  v_subtotal numeric;
  v_tax_rate numeric;
  v_tax_amount numeric;
  v_total numeric;
BEGIN
  -- Sum line items
  SELECT COALESCE(SUM(line_total), 0)
  INTO v_subtotal
  FROM public.invoice_line_items
  WHERE invoice_id = p_invoice_id;

  -- Get tax_rate
  SELECT COALESCE(tax_rate, 0)
  INTO v_tax_rate
  FROM public.invoices
  WHERE id = p_invoice_id;

  -- Compute totals
  v_tax_amount := v_subtotal * v_tax_rate;
  v_total := v_subtotal + v_tax_amount;

  -- Update invoice
  UPDATE public.invoices
  SET
    subtotal   = v_subtotal,
    tax_amount = v_tax_amount,
    total      = v_total,
    updated_at = NOW()
  WHERE id = p_invoice_id;
END;

DECLARE
  v_total numeric(12,2) := 0;
  v_paid numeric(12,2) := 0;
BEGIN
  SELECT COALESCE(i.total, 0)
  INTO v_total
  FROM public.invoices i
  WHERE i.id = p_invoice_id;

  SELECT COALESCE(SUM(p.amount), 0)
  INTO v_paid
  FROM public.payments p
  WHERE p.invoice_id = p_invoice_id;

  UPDATE public.invoices i
  SET
    amount_paid = v_paid,
    balance_due = GREATEST(v_total - v_paid, 0)
  WHERE i.id = p_invoice_id;
END;

declare
  v_total numeric := 0;
  v_paid numeric := 0;
  v_balance numeric := 0;
  v_due_date date;
  v_now date := (now() at time zone 'utc')::date;
  v_status text;
begin
  select coalesce(total, 0), due_date
    into v_total, v_due_date
  from public.invoices
  where id = p_invoice_id;

  select coalesce(sum(amount), 0)
    into v_paid
  from public.payments
  where invoice_id = p_invoice_id;

  v_balance := v_total - v_paid;

  -- status rules
  if v_total = 0 then
    v_status := 'draft';
  elsif v_balance <= 0 then
    v_status := 'paid';
  elsif v_paid > 0 and v_balance > 0 then
    v_status := 'partially_paid';
  else
    if v_due_date is not null and v_due_date < v_now then
      v_status := 'overdue';
    else
      v_status := 'sent';
    end if;
  end if;

  update public.invoices
  set amount_paid = v_paid,
      balance_due = greatest(v_balance, 0),
      status = v_status,
      updated_at = now()
  where id = p_invoice_id;
end;

