declare
  v_old uuid;
  v_new uuid;
begin
  -- Determine old/new invoice ids based on operation
  if (tg_op = 'DELETE') then
    v_old := old.invoice_id;
    perform public.recalculate_invoice_totals(v_old);
    return old;
  end if;

  v_new := new.invoice_id;

  if (tg_op = 'UPDATE') then
    v_old := old.invoice_id;

    -- If invoice_id changed, recalc both invoices
    if v_old is distinct from v_new then
      perform public.recalculate_invoice_totals(v_old);
    end if;
  end if;

  perform public.recalculate_invoice_totals(v_new);
  return new;
end;

